const seaMoonSheet=new Image();seaMoonSheet.assetSrc='assets/sea-moon-v2.png';
function beginSeaMoon(e){let angle=Math.atan2(p.y-e.y,p.x-e.x);e.state='attack';e.elapsed=0;e.struck=false;e.facing=Math.cos(angle)-Math.sin(angle)<0?-1:1;e.attack={pattern:'moonTrackingBubble',bespoke:true,windup:2.2,origin:{x:e.x,y:e.y},angle,center:{x:p.x,y:p.y},locked:false,fired:false};}
const seaMoonAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r8e6')return seaMoonAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);let a=e.attack;
 if(a?.pattern!=='moonTrackingBubble'){e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=380&&clear){beginSeaMoon(e);return;}e.state='idle';if(d>800&&!e.aware)return;if(e.nav<=0){e.nav=.65;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,64*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,20)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}
 if(dist(e,a.origin)>24){e.attack=null;e.state='idle';e.t=1.5;return;}if(!a.locked){if(dist(e,p)>450||!lineClear(e,p)){e.attack=null;e.state='idle';e.t=2;return;}a.center={x:p.x,y:p.y};}
 e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;if(e.elapsed>=1.2)a.locked=true;
 if(!a.fired&&e.elapsed>=2.2){a.fired=true;e.struck=true;if(dist(p,a.center)<=120+1e-8&&lineClear(a.origin,a.center)&&lineClear(a.center,p))hurt(78);playSound('impact',e.x,e.y);burst(a.center.x,a.center.y,120,'#abc8f4');}
 if(e.elapsed>=3.2){e.attack=null;e.state='idle';e.t=3.2;}
};
const seaMoonDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r8e6'||!seaMoonSheet.complete||!seaMoonSheet.naturalWidth||!seaMoonSheet.naturalHeight)return seaMoonDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0);if(e.hp<=0)f={row:2,col:3};else if(e.attack?.pattern==='moonTrackingBubble')f={row:2,col:e.elapsed<1.2?0:e.elapsed<2.2?1:e.elapsed<2.55?2:3};let q=project(e.x,e.y),sw=seaMoonSheet.naturalWidth/4,sh=seaMoonSheet.naturalHeight/3,w=245,h=w*sh/sw,anchor=[.85,.83,.86][f.row];ctx.save();ctx.translate(q.x,q.y-(e.hp>0?Math.sin((e.anim||0)*2.5)*5:0));ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,seaMoonSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(seaMoonSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;};
const seaMoonSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r8e6'?150:seaMoonSizeBase(e);
const seaMoonGroundBase=drawGroundEffects;drawGroundEffects=()=>{seaMoonGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r8e6'):enemies)){let a=e.attack;if(e.species!=='r8e6'||e.hp<=0||a?.pattern!=='moonTrackingBubble'||e.elapsed>=2.55||!visibleAt(a.center.x,a.center.y))continue;let color=a.fired?'#e6e6ff':a.locked?'#f4bf82':'#a3c6f0';groundRing(a.center.x,a.center.y,120,color,a.fired?4:a.locked?3:1);if(!a.fired)groundRing(a.center.x,a.center.y,a.locked?Math.max(4,120*(2.2-e.elapsed)):28,color,2);if(!a.locked){let q=project(e.x,e.y),r=project(a.center.x,a.center.y);ctx.save();ctx.strokeStyle='#9ac9ee66';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(q.x,q.y-50);ctx.lineTo(r.x,r.y-20);ctx.stroke();ctx.restore();}}};
